<template>
  <div class="sg-client-page sg3-utility-page"><PublicNavbar /><main class="sg3-container sg3-profile-main"><div class="sg3-page-head"><div><div class="sg3-breadcrumbs"><router-link to="/profile">Tài khoản</router-link><span>/</span><strong>Ví SportGo</strong></div><p class="sg3-kicker">Tài chính cá nhân</p><h1>Ví SportGo</h1><p>Số dư dùng để thanh toán booking và nhận các khoản hoàn tiền.</p></div><router-link class="sg3-button sg3-button--primary" to="/bookings"><AppIcon name="calendar" :size="17" />Lịch đặt sân</router-link></div><ClientAccountNav />
    <div v-if="loading" class="sg3-empty"><div><strong>Đang tải thông tin ví</strong><p>Đang đồng bộ số dư và lịch sử giao dịch.</p></div></div><div v-else-if="error" class="sg3-error"><div><strong>Không tải được ví</strong><p>{{ error }}</p><button class="sg3-button sg3-button--primary" type="button" @click="loadWallet">Thử lại</button></div></div><template v-else><section class="sg3-card sg3-wallet-balance"><div><span>Số dư khả dụng</span><strong>{{ money(wallet.balance) }}</strong></div><div><span>Đang khóa</span><strong>{{ money(wallet.locked_balance) }}</strong></div><span class="sg3-wallet-status">{{ statusLabel(wallet.status) }}</span></section><section class="sg3-card sg3-ledger-card"><header><div><p class="sg3-kicker">Biến động số dư</p><h2>Lịch sử ví</h2></div><button class="sg3-button sg3-button--secondary" type="button" @click="loadWallet"><AppIcon name="refresh" :size="16" />Làm mới</button></header><div v-if="!ledgers.length" class="sg3-empty sg3-empty--inline"><div><strong>Ví chưa có giao dịch</strong><p>Các khoản thanh toán hoặc hoàn tiền sẽ xuất hiện tại đây.</p></div></div><div v-else class="sg3-ledger-list"><article v-for="ledger in ledgers" :key="ledger.id"><div><strong>{{ ledger.note || typeLabel(ledger.type) }}</strong><small>{{ ledger.transaction_code }} · {{ formatDate(ledger.created_at) }}</small></div><div class="sg3-ledger-amount" :class="ledger.direction"><strong>{{ ledger.direction === 'credit' ? '+' : '-' }}{{ money(ledger.amount) }}</strong><small>Số dư {{ money(ledger.balance_after) }}</small></div></article></div></section></template></main></div>
</template>
<script>
import AppIcon from "../../components/AppIcon.vue"; import ClientAccountNav from "../../components/ClientAccountNav.vue"; import PublicNavbar from "../../components/PublicNavbar.vue"; import { bookingService } from "../../services/bookingService.js";
export default { name:"ClientWallet", components:{ AppIcon, ClientAccountNav, PublicNavbar }, data(){ return { wallet:{ balance:0, locked_balance:0, status:"active" }, ledgers:[], loading:true, error:"" }; }, mounted(){ this.loadWallet(); }, methods:{ async loadWallet(){ this.loading=true; this.error=""; try{ const response=await bookingService.getWallet(); this.wallet=response.wallet||this.wallet; this.ledgers=response.ledgers||[]; }catch(error){ this.error=error.message||"Không thể tải thông tin ví."; }finally{ this.loading=false; } }, money(value){ return new Intl.NumberFormat("vi-VN",{style:"currency",currency:"VND",maximumFractionDigits:0}).format(Number(value||0)); }, formatDate(value){ return value?new Date(value).toLocaleString("vi-VN"):"-"; }, statusLabel(status){ return {active:"Đang hoạt động",locked:"Đang khóa",suspended:"Tạm ngưng"}[status]||status; }, typeLabel(type){ return {deposit:"Nạp tiền",payment:"Thanh toán booking",refund:"Hoàn tiền",withdrawal:"Rút tiền",adjustment:"Điều chỉnh"}[type]||type; } } };
</script>
